function win32Normalize(path) {
	const len = path.length;
	if (len === 0) return ".";
	let rootEnd = 0;
	/** @type {string | undefined} */
	let device;
	let isAbsolute = false;
	const code = path.charCodeAt(0);

	if (len === 1) {
		return isPosixPathSeparator(code) ? "\\" : path;
	}

	if (isPathSeparator(code)) {
		// Possible UNC root; an initial separator means an absolute path.
		isAbsolute = true;

		if (isPathSeparator(path.charCodeAt(1))) {
			// Matched double path separator at beginning
			let j = 2;
			let last = j;
			while (j < len && !isPathSeparator(path.charCodeAt(j))) j++;
			if (j < len && j !== last) {
				const firstPart = path.slice(last, j);
				last = j;
				while (j < len && isPathSeparator(path.charCodeAt(j))) j++;
				if (j < len && j !== last) {
					last = j;
					while (j < len && !isPathSeparator(path.charCodeAt(j))) j++;
					if (j === len || j !== last) {
						if (firstPart === "." || firstPart === "?") {
							// Device root, e.g. `\\.\pipe\…` or `\\?\C:\…`
							device = `\\\\${firstPart}`;
							rootEnd = 4;
						} else if (j === len) {
							// Matched a UNC root only
							return `\\\\${firstPart}\\${path.slice(last)}\\`;
						} else {
							// Matched a UNC root with leftovers
							device = `\\\\${firstPart}\\${path.slice(last, j)}`;
							rootEnd = j;
						}
					}
				}
			}
		} else {
			rootEnd = 1;
		}
	} else if (isWindowsDeviceRoot(code) && path.charCodeAt(1) === CHAR_COLON) {
		// Possible device root
		device = path.slice(0, 2);
		rootEnd = 2;
		if (len > 2 && isPathSeparator(path.charCodeAt(2))) {
			isAbsolute = true;
			rootEnd = 3;
		}
	}

	let tail =
		rootEnd < len
			? normalizeString(path.slice(rootEnd), !isAbsolute, "\\", isPathSeparator)
			: "";
	if (tail.length === 0 && !isAbsolute) tail = ".";
	if (tail.length > 0 && isPathSeparator(path.charCodeAt(len - 1))) {
		tail += "\\";
	}
	if (!isAbsolute && device === undefined && path.includes(":")) {
		// A relative path that wasn't resolved to a device must not turn into
		// something Windows could read as an absolute/drive path (CVE-2024-36139).
		if (
			tail.length >= 2 &&
			isWindowsDeviceRoot(tail.charCodeAt(0)) &&
			tail.charCodeAt(1) === CHAR_COLON
		) {
			return `.\\${tail}`;
		}
		let index = path.indexOf(":");
		do {
			if (index === len - 1 || isPathSeparator(path.charCodeAt(index + 1))) {
				return `.\\${tail}`;
			}
		} while ((index = path.indexOf(":", index + 1)) !== -1);
	}
	if (device === undefined) {
		return isAbsolute ? `\\${tail}` : tail;
	}
	return isAbsolute ? `${device}\\${tail}` : `${device}${tail}`;
}

function win32Dirname(path) {
	const len = path.length;
	if (len === 0) return ".";
	let rootEnd = -1;
	let offset = 0;
	const code = path.charCodeAt(0);

	if (len === 1) {
		return isPathSeparator(code) ? path : ".";
	}

	if (isPathSeparator(code)) {
		// Possible UNC root
		rootEnd = offset = 1;

		if (isPathSeparator(path.charCodeAt(1))) {
			let j = 2;
			let last = j;
			while (j < len && !isPathSeparator(path.charCodeAt(j))) j++;
			if (j < len && j !== last) {
				last = j;
				while (j < len && isPathSeparator(path.charCodeAt(j))) j++;
				if (j < len && j !== last) {
					last = j;
					while (j < len && !isPathSeparator(path.charCodeAt(j))) j++;
					if (j === len) {
						// Matched a UNC root only
						return path;
					}
					if (j !== last) {
						// Matched a UNC root with leftovers
						rootEnd = offset = j + 1;
					}
				}
			}
		}
	} else if (isWindowsDeviceRoot(code) && path.charCodeAt(1) === CHAR_COLON) {
		rootEnd = len > 2 && isPathSeparator(path.charCodeAt(2)) ? 3 : 2;
		offset = rootEnd;
	}

	let end = -1;
	let matchedSlash = true;
	for (let i = len - 1; i >= offset; --i) {
		if (isPathSeparator(path.charCodeAt(i))) {
			if (!matchedSlash) {
				end = i;
				break;
			}
		} else {
			matchedSlash = false;
		}
	}

	if (end === -1) {
		if (rootEnd === -1) return ".";
		end = rootEnd;
	}
	return path.slice(0, end);
}

function normalizeString(path, allowAboveRoot, separator, isSeparator) {
	let res = "";
	let lastSegmentLength = 0;
	let lastSlash = -1;
	let dots = 0;
	let code = 0;
	for (let i = 0; i <= path.length; ++i) {
		if (i < path.length) {
			code = path.charCodeAt(i);
		} else if (isSeparator(code)) {
			break;
		} else {
			code = CHAR_FORWARD_SLASH;
		}

		if (isSeparator(code)) {
			if (lastSlash === i - 1 || dots === 1) {
				// NOOP
			} else if (dots === 2) {
				if (
					res.length < 2 ||
					lastSegmentLength !== 2 ||
					res.charCodeAt(res.length - 1) !== CHAR_DOT ||
					res.charCodeAt(res.length - 2) !== CHAR_DOT
				) {
					if (res.length > 2) {
						const lastSlashIndex = res.lastIndexOf(separator);
						if (lastSlashIndex === -1) {
							res = "";
							lastSegmentLength = 0;
						} else {
							res = res.slice(0, lastSlashIndex);
							lastSegmentLength = res.length - 1 - res.lastIndexOf(separator);
						}
						lastSlash = i;
						dots = 0;
						continue;
					} else if (res.length !== 0) {
						res = "";
						lastSegmentLength = 0;
						lastSlash = i;
						dots = 0;
						continue;
					}
				}
				if (allowAboveRoot) {
					res += res.length > 0 ? `${separator}..` : "..";
					lastSegmentLength = 2;
				}
			} else {
				if (res.length > 0) {
					res += `${separator}${path.slice(lastSlash + 1, i)}`;
				} else {
					res = path.slice(lastSlash + 1, i);
				}
				lastSegmentLength = i - lastSlash - 1;
			}
			lastSlash = i;
			dots = 0;
		} else if (code === CHAR_DOT && dots !== -1) {
			++dots;
		} else {
			dots = -1;
		}
	}
	return res;
}

function basename(path, suffix) {
	let start = 0;
	let end = -1;
	let matchedSlash = true;

	if (
		suffix !== undefined &&
		suffix.length > 0 &&
		suffix.length <= path.length
	) {
		if (suffix === path) return "";
		let extIdx = suffix.length - 1;
		let firstNonSlashEnd = -1;
		for (let i = path.length - 1; i >= 0; --i) {
			const code = path.charCodeAt(i);
			if (code === CHAR_FORWARD_SLASH) {
				if (!matchedSlash) {
					start = i + 1;
					break;
				}
			} else {
				if (firstNonSlashEnd === -1) {
					matchedSlash = false;
					firstNonSlashEnd = i + 1;
				}
				if (extIdx >= 0) {
					if (code === suffix.charCodeAt(extIdx)) {
						if (--extIdx === -1) {
							end = i;
						}
					} else {
						extIdx = -1;
						end = firstNonSlashEnd;
					}
				}
			}
		}

		if (start === end) {
			end = firstNonSlashEnd;
		} else if (end === -1) {
			end = path.length;
		}
		return path.slice(start, end);
	}
	for (let i = path.length - 1; i >= 0; --i) {
		if (path.charCodeAt(i) === CHAR_FORWARD_SLASH) {
			if (!matchedSlash) {
				start = i + 1;
				break;
			}
		} else if (end === -1) {
			matchedSlash = false;
			end = i + 1;
		}
	}

	if (end === -1) return "";
	return path.slice(start, end);
}

function computeFindMatch(request, field) {
	const requestLen = request.length;
	const requestEndsWithSlash =
		requestLen > 0 && request.charCodeAt(requestLen - 1) === slashCode;
	const requestHasStar = request.includes("*");

	if (
		!requestHasStar &&
		!requestEndsWithSlash &&
		Object.prototype.hasOwnProperty.call(field, request)
	) {
		const target = /** @type {{ [k: string]: MappingValue }} */ (field)[
			request
		];

		return [target, "", false, false, request];
	}

	/** @type {string} */
	let bestMatch = "";
	/** @type {FieldKeyInfo | null} */
	let bestMatchInfo = null;
	/** @type {string | undefined} */
	let bestMatchSubpath;

	const infos = getFieldKeyInfos(field);

	for (let i = 0; i < infos.length; i++) {
		const info = infos[i];
		const { key, patternIndex } = info;

		if (patternIndex !== -1) {
			if (
				!info.isValidPattern ||
				!request.startsWith(info.wildcardPrefix) ||
				requestLen < key.length ||
				!request.endsWith(info.wildcardSuffix) ||
				patternKeyCompare(bestMatch, key) !== 1
			) {
				continue;
			}
			bestMatch = key;
			bestMatchInfo = info;
			bestMatchSubpath = request.slice(
				patternIndex,
				requestLen - info.wildcardSuffix.length,
			);
		} else if (
			info.isLegacySubpath &&
			request.startsWith(key) &&
			patternKeyCompare(bestMatch, key) === 1
		) {
			bestMatch = key;
			bestMatchInfo = info;
			bestMatchSubpath = request.slice(key.length);
		}
	}

	if (bestMatch === "") return null;

	const target =
		/** @type {{ [k: string]: MappingValue }} */
		(field)[bestMatch];

	return [
		target,
		/** @type {string} */ (bestMatchSubpath),
		/** @type {FieldKeyInfo} */ (bestMatchInfo).isSubpathMapping,
		/** @type {FieldKeyInfo} */ (bestMatchInfo).isPattern,
		bestMatch,
	];
}
